    getPropertyValueManager(property: Property): PropertyValueManager<unknown> {
        switch (property.key) {
            case sysml_lionwebBase.INSTANCE.IType_isAbstract.key: return this._isAbstract;
            case sysml_lionwebBase.INSTANCE.IType_isSufficient.key: return this._isSufficient;
            case sysml_lionwebBase.INSTANCE.IType_isConjugated.key: return this._isConjugated;
            case sysml_lionwebBase.INSTANCE.IElement_elementId.key: return this._elementId;
            case sysml_lionwebBase.INSTANCE.IElement_declaredShortName.key: return this._declaredShortName;
            case sysml_lionwebBase.INSTANCE.IElement_declaredName.key: return this._declaredName;
            case sysml_lionwebBase.INSTANCE.IElement_shortName.key: return this._shortName;
            case sysml_lionwebBase.INSTANCE.IElement_name.key: return this._name;
            case sysml_lionwebBase.INSTANCE.IElement_qualifiedName.key: return this._qualifiedName;
            case sysml_lionwebBase.INSTANCE.IElement_isImpliedIncluded.key: return this._isImpliedIncluded;
            case sysml_lionwebBase.INSTANCE.IElement_isLibraryElement.key: return this._isLibraryElement;
            default: return super.getPropertyValueManager(property);
        }
    }

